import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  it('validates a function-valued definition against the schema returned for that call', async () => {
    let schemaVersion = 0;
    const definition = (): ToolDefinition => ({
      name: 'versioned',
      description: 'schema changes between calls',
      inputSchema:
        schemaVersion === 0
          ? {type: 'object', properties: {a: {type: 'string'}}, required: ['a']}
          : {type: 'object', properties: {b: {type: 'string'}}, required: ['b']},
    });
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(definition, async () => {
      executorCalls += 1;
      return 'ok';
    });

    const accepted = await registry.execute('versioned', {a: 'x'});
    schemaVersion = 1;
    const rejected = await registry.execute('versioned', {a: 'x'});

    expect({accepted: accepted.result, rejectedMentionsB: rejected.result.includes('b'), executorCalls}).toEqual({
      accepted: 'ok',
      rejectedMentionsB: true,
      executorCalls: 1,
    });
  });

  it('passes valid input with an undeclared extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => {
        received.push(input);
        return 'ok';
      }
    );

    await registry.execute('get_weather', {location: 'Paris', units: 'metric'});

    expect(received).toEqual([{location: 'Paris', units: 'metric'}]);
  });

  it('compiles a static tool schema once across ten execute calls', async () => {
    let schemaReads = 0;
    const definition: ToolDefinition = {
      name: 'static_tool',
      description: 'static schema',
      get inputSchema() {
        schemaReads += 1;
        return {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};
      },
    };
    const registry = new ToolRegistry();
    registry.register(definition, async () => 'ok');
    const readsAfterRegister = schemaReads;

    for (let i = 0; i < 10; i += 1) await registry.execute('static_tool', {a: 'x'});

    expect({readsAfterRegister, readsAfterExecutes: schemaReads}).toEqual({
      readsAfterRegister: 1,
      readsAfterExecutes: 1,
    });
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with an undeclared extra property to the executor unchanged, exactly once](../../src/orchestration/tools/registry.test.ts#L33)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws Unknown tool for an unregistered name](../../src/orchestration/tools/registry.test.ts#L75)).

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static tool schema once across ten execute calls](../../src/orchestration/tools/registry.test.ts#L53)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates a function-valued definition against the schema returned for that call](../../src/orchestration/tools/registry.test.ts#L5)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

